//! The About window (`?about`): the app's name, version and maker, its own
//! license, and the licenses of everything it includes. The texts are
//! compiled in, so every build carries the notices its licenses require.

use subduer_core::types::AboutInfo;
use tauri::{AppHandle, Manager, Runtime, WebviewUrl, WebviewWindowBuilder};

/// The one About window; capabilities grant it by this label.
pub const LABEL: &str = "about";

const LICENSE: &str = include_str!("../../LICENSE");
/// Regenerated by `tools/third-party-notices.sh`.
const NOTICES: &str = include_str!("../../THIRD-PARTY-NOTICES.txt");

/// Opens the About window, or brings it to the front.
pub fn open<R: Runtime>(app: &AppHandle<R>) -> tauri::Result<()> {
    if let Some(window) = app.get_webview_window(LABEL) {
        let _ = window.unminimize();
        return window.set_focus();
    }
    WebviewWindowBuilder::new(app, LABEL, WebviewUrl::App("index.html?about".into()))
        .title(format!("About {}", app.package_info().name))
        .inner_size(760.0, 720.0)
        .min_inner_size(480.0, 360.0)
        .disable_drag_drop_handler()
        .build()?;
    Ok(())
}

#[tauri::command]
pub fn about_info<R: Runtime>(app: AppHandle<R>) -> AboutInfo {
    let info = app.package_info();
    AboutInfo {
        name: info.name.clone(),
        version: info.version.to_string(),
        maker: crate::menu::MAKER.to_owned(),
        copyright: app.config().bundle.copyright.clone().unwrap_or_default(),
        license: LICENSE.to_owned(),
        notices: NOTICES.to_owned(),
    }
}
